import argparse
import bisect
import json
import pathlib
import timeit
from datetime import datetime

import numpy as np

import utils
from save_analytic_data import *
'''
 Shape of each matrix in npz

 max_id_count = ( len(obj_type), time_interval/step, step/step_for_count +1 )
 timestamp = ( time_interval/step, step/step_for_count )

 for motion npz
 timestamp = ( event_count )
'''


def CountFromDB(cam_id: str, start: int, end: int) -> np.array:
    if cam_id == 'unittest':
        return [0 for _ in range(utils.NumDetectTypes)]

    _, id_count = GetEventDataWithTime(cam_id, start, end, is_get_raws=False)
    new_id_count, _ = MakeMaxCountArray([id_count], [end], end - start)
    new_max = new_id_count[:, :, -1].reshape((-1))
    new_max = utils.AdjustDataSize(new_max, 0, utils.NumDetectTypes)

    return new_max


def MotionCount(data_path: pathlib.Path, cam_id: str, start_time: int,
                end_time: int) -> int:

    raw_data_paths = utils.GetAnalyticDataPaths(data_path,
                                                cam_id,
                                                start_time,
                                                end_time,
                                                is_motion=True)
    raw_data_paths += utils.GetAnalyticDataPaths(
        data_path,
        cam_id,
        start_time,
        end_time,
        suffix=utils.NPZSuffix.COMBINE,
        is_motion=True)

    total_count = 0
    for path in raw_data_paths:
        if utils.NPZSuffix.COMBINE in path.name:
            raw_data = utils.LoadNPZ(path)
            if not raw_data: continue
            timestamps = raw_data['timestamp']

            lo_index = bisect.bisect_right(timestamps, start_time)
            hi_index = bisect.bisect_left(timestamps, end_time)

            if lo_index == hi_index: continue
            if 'event_count' in raw_data:
                count_list = raw_data['event_count']
                if hi_index == len(count_list): hi_index -= 1
                if lo_index == 0:
                    total_count += int(count_list[hi_index])
                else:
                    lo_index -= 1
                    total_count += int(count_list[hi_index]) - int(
                        count_list[lo_index])
            else:
                total_count += hi_index - lo_index
        else:
            # GetAnalyticDataPaths is delibrately getting one more npz after end_time
            # since the npz may contain data before end_time
            # except single event motion npz
            timestamps = utils.GetNPZEndTime(path.name, "")
            if timestamps > end_time: continue
            total_count += 1

    return total_count


def DetectCount(data_path: pathlib.Path, cam_id: str, start_time: int,
                end_time: int, step: int):
    raw_data_paths = utils.GetAnalyticDataPaths(data_path, cam_id, start_time,
                                                end_time)
    all_detect_count = []
    data_per_file = []
    time_per_file = []
    obj_types = utils.ObjectIndex.items()
    for path in raw_data_paths:
        raw_data = utils.LoadNPZ(path)
        if not raw_data: continue
        id_data = raw_data['max_id_count'][:, :, :-1].reshape(
            (utils.NumDetectTypes, -1))
        timestamps = raw_data['timestamp'].flatten()
        data_per_file.append((id_data, timestamps))
        time_per_file.append(timestamps[-1])

    for start in range(start_time, end_time, step):
        end = start + step if start + step <= end_time else end_time

        lo_idx = bisect.bisect_right(time_per_file, start)
        hi_idx = bisect.bisect_left(time_per_file, end)

        data_interest = data_per_file[lo_idx:hi_idx + 1]

        # all object types except motion
        all_max_count = [np.zeros((utils.NumDetectTypes), dtype=np.int32)]

        if not data_interest:  # no npz
            all_max_count.append(
                np.zeros((utils.NumDetectTypes), dtype=np.int32))
        else:
            for i_data, t_data in data_interest:
                start_idx = bisect.bisect_right(t_data, start)
                end_idx = bisect.bisect_right(t_data, end)
                data_in_range = i_data[:, start_idx:end_idx]
                if data_in_range.size != 0:
                    all_max_count.append(
                        utils.AdjustDataSize(np.max(data_in_range, axis=1), 0,
                                             utils.NumDetectTypes))

        max_count = np.max(all_max_count, axis=0)
        count_per_step = {
            o_type: int(max_count[o_idx])
            for o_type, o_idx in obj_types
        }

        if cam_id == "unittest":
            count_per_step['motion'] = MotionCount(data_path, cam_id, start,
                                                   end)

        all_detect_count.append({
            'timestamp': [start, end],
            'detect_count': count_per_step
        })

    result_json_output = {cam_id: all_detect_count}
    print(json.dumps(result_json_output))  # for BE to parse

    if cam_id == "unittest":
        with open("/tmp/count_{}_{}.json".format(start_time, end_time),
                  'w') as fp:
            json.dump(result_json_output, fp)


def Main():
    parser = argparse.ArgumentParser(
        "Count all detection types and motion event in certain time range")

    parser.add_argument(
        "-id",
        dest="cam_id",
        nargs='+',
        help='target camera id to do detect count, multiple ids are allowed',
        type=str)
    parser.add_argument("-data",
                        dest="data_path",
                        help='analytic data directory path',
                        type=str)
    parser.add_argument('-s',
                        dest='start_time',
                        help='start timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument('-e',
                        dest='end_time',
                        help='end timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument(
        '-step',
        dest='step',
        help='time step (in minute) for the given time interval',
        default=30,
        type=int)

    args = parser.parse_args()

    data_path = pathlib.Path(args.data_path)

    if not data_path.is_dir():
        raise FileNotFoundError(
            "Cannot find heatmap dir [{}]".format(data_path))

    target_min = args.step % 60
    if target_min == 0: target_min = 60
    start_time = utils.RoundTimeToNearestMin(args.start_time,
                                             target_min,
                                             return_ts=True)
    end_time = utils.RoundTimeToNearestMin(args.end_time,
                                           target_min,
                                           return_ts=True)

    now = int(datetime.now().timestamp() * 1000)
    if end_time - now > 0:  # make sure end_time doesn't exceed current time
        end_time = utils.FloorTimeToNearestMin(now, target_min, return_ts=True)

    if start_time > end_time:
        raise ValueError("start time is later than end time")

    step = int(args.step * 60 * 1000)
    if args.cam_id:
        for cam_id in args.cam_id:
            DetectCount(data_path, cam_id, start_time, end_time, step)


if __name__ == "__main__":
    Main()
